import AppKit
import CryptoKit
import Foundation
import UniformTypeIdentifiers

private let privatePasteboardTypes: Set<String> = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "com.typeit4me.clipping",
    "de.petermaurer.TransientPasteboardType"
]

private let fileType = NSPasteboard.PasteboardType.fileURL.rawValue
private let stringType = NSPasteboard.PasteboardType.string.rawValue
private let colorType = NSPasteboard.PasteboardType.color.rawValue
private let urlType = UTType.url.identifier

struct ClipboardRepresentation: Codable {
    let type: String
    let data: Data
}

struct ClipboardPayload: Codable {
    let items: [[ClipboardRepresentation]]

    static func capture(from board: NSPasteboard) -> Self? {
        let items = board.pasteboardItems ?? []
        let types = (board.types ?? []) + items.flatMap(\.types)
        guard privatePasteboardTypes.isDisjoint(with: types.map(\.rawValue)) else { return nil }
        let captured = items.compactMap { item -> [ClipboardRepresentation]? in
            let hasFile = item.types.contains(.fileURL)
            let representations = item.types.compactMap { type -> ClipboardRepresentation? in
                guard isSupported(type.rawValue), !hasFile || type == .fileURL,
                      let data = item.data(forType: type) else { return nil }
                return ClipboardRepresentation(type: type.rawValue, data: data)
            }
            return representations.isEmpty ? nil : representations
        }
        return captured.isEmpty ? nil : Self(items: captured)
    }

    private static func isSupported(_ type: String) -> Bool {
        let explicit = [fileType, stringType, colorType, NSPasteboard.PasteboardType.html.rawValue,
                        NSPasteboard.PasteboardType.rtf.rawValue, NSPasteboard.PasteboardType.rtfd.rawValue,
                        urlType, "com.apple.flat-rtfd", "public.pdf"]
        if explicit.contains(type) { return true }
        guard let utType = UTType(type) else { return false }
        return utType.conforms(to: .image) || utType.conforms(to: .movie)
            || utType.conforms(to: .video) || utType.conforms(to: .plainText)
    }

    func write(to board: NSPasteboard, plainText: Bool = false) -> Bool {
        if plainText {
            guard let text = self.plainText else { return false }
            let item = NSPasteboardItem()
            guard item.setString(text, forType: .string) else { return false }
            board.clearContents()
            return board.writeObjects([item])
        }
        let ready = items.map { representations in
            let item = NSPasteboardItem()
            for entry in representations {
                item.setData(entry.data, forType: NSPasteboard.PasteboardType(entry.type))
            }
            return item
        }
        guard !ready.isEmpty else { return false }
        board.clearContents()
        return board.writeObjects(ready)
    }

    var files: [URL] {
        items.flatMap { item in
            item.compactMap { entry in
                guard entry.type == fileType, let text = String(data: entry.data, encoding: .utf8),
                      let url = URL(string: text), url.isFileURL else { return nil }
                return url
            }
        }
    }

    var missingFile: URL? {
        files.first { !FileManager.default.fileExists(atPath: $0.path) }
    }

    var imageData: Data? {
        let images = items.joined().filter { UTType($0.type)?.conforms(to: .image) == true || $0.type == "public.pdf" }
        return images.first(where: { $0.type == UTType.png.identifier })?.data ?? images.first?.data
    }

    var video: ClipboardRepresentation? {
        items.joined().first { UTType($0.type)?.conforms(to: .movie) == true || UTType($0.type)?.conforms(to: .video) == true }
    }

    var plainText: String? {
        let strings: [String] = items.compactMap { item in
            if let text = Self.text(in: item) { return text }
            return Self.nativeColor(in: item)?.hex
        }
        return strings.isEmpty ? nil : strings.joined(separator: "\n")
    }

    private static func text(in item: [ClipboardRepresentation]) -> String? {
        if let value = item.first(where: { $0.type == stringType }),
           let text = String(data: value.data, encoding: .utf8) { return text }
        for entry in item {
            if entry.type == urlType,
               let text = String(data: entry.data, encoding: .utf8) { return text }
            if UTType(entry.type)?.conforms(to: .plainText) == true {
                let encoding: String.Encoding = entry.type.contains("utf16") ? .utf16 : .utf8
                if let text = String(data: entry.data, encoding: encoding) { return text }
            }
        }
        for entry in item {
            switch entry.type {
            case NSPasteboard.PasteboardType.rtf.rawValue:
                if let text = NSAttributedString(rtf: entry.data, documentAttributes: nil)?.string { return text }
            case NSPasteboard.PasteboardType.rtfd.rawValue, "com.apple.flat-rtfd":
                if let text = NSAttributedString(rtfd: entry.data, documentAttributes: nil)?.string { return text }
            case NSPasteboard.PasteboardType.html.rawValue:
                if let html = String(data: entry.data, encoding: .utf8) { return Self.stripHTML(html) }
            default:
                continue
            }
        }
        return nil
    }

    private static func stripHTML(_ html: String) -> String {
        let cleaned = html
            .replacingOccurrences(of: "(?is)<!--.*?-->|<(script|style|head)\\b[^>]*>.*?</\\1\\s*>", with: "", options: .regularExpression)
            .replacingOccurrences(of: "(?i)<br\\s*/?>|</(?:p|div|li|tr|h[1-6])\\s*>", with: "\n", options: .regularExpression)
            .replacingOccurrences(of: "(?s)<[^>]*>", with: "", options: .regularExpression)
        let replacements = ["&nbsp;": " ", "&lt;": "<", "&gt;": ">", "&quot;": "\"", "&apos;": "'"]
        var text = cleaned
        for (entity, value) in replacements {
            text = text.replacingOccurrences(of: entity, with: value)
        }
        if let regex = try? NSRegularExpression(pattern: "&#([0-9]+|x[0-9a-fA-F]+);") {
            for match in regex.matches(in: text, range: NSRange(text.startIndex..., in: text)).reversed() {
                guard let whole = Range(match.range, in: text), let digits = Range(match.range(at: 1), in: text) else { continue }
                let value = text[digits]
                let number = value.hasPrefix("x") ? UInt32(value.dropFirst(), radix: 16) : UInt32(value)
                if let number, let scalar = UnicodeScalar(number) { text.replaceSubrange(whole, with: String(scalar)) }
            }
        }
        return text.replacingOccurrences(of: "&amp;", with: "&").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func nativeColor(in item: [ClipboardRepresentation]) -> ClipColor? {
        guard let entry = item.first(where: { $0.type == colorType }),
              let color = try? NSKeyedUnarchiver.unarchivedObject(ofClass: NSColor.self, from: entry.data),
              let rgb = color.usingColorSpace(.sRGB) else { return nil }
        return ClipColor(red: rgb.redComponent, green: rgb.greenComponent, blue: rgb.blueComponent, alpha: rgb.alphaComponent)
    }

    var color: ClipColor? {
        guard let first = items.first else { return nil }
        if let native = Self.nativeColor(in: first) { return native }
        if first.contains(where: { $0.type == colorType }) {
            let board = NSPasteboard.withUniqueName()
            defer { board.releaseGlobally() }
            if Self(items: [first]).write(to: board), let rgb = NSColor(from: board)?.usingColorSpace(.sRGB) {
                return ClipColor(red: rgb.redComponent, green: rgb.greenComponent, blue: rgb.blueComponent, alpha: rgb.alphaComponent)
            }
        }
        return Self.text(in: first).flatMap { ClipColor(hex: $0.trimmingCharacters(in: .whitespacesAndNewlines)) }
    }

    var fingerprint: String {
        var hasher = SHA256()
        for item in items {
            for entry in item.sorted(by: { $0.type < $1.type }) {
                let type = Data(entry.type.utf8)
                var typeSize = UInt64(type.count).bigEndian
                var dataSize = UInt64(entry.data.count).bigEndian
                withUnsafeBytes(of: &typeSize) { hasher.update(bufferPointer: $0) }
                hasher.update(data: type)
                withUnsafeBytes(of: &dataSize) { hasher.update(bufferPointer: $0) }
                hasher.update(data: entry.data)
            }
            hasher.update(data: Data(repeating: 0, count: 8))
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    func summary(source: String, date: Date = Date()) -> ClipSummary {
        let files = self.files
        let kind: ClipKind
        let title: String
        let searchable: String
        let swatch: ClipColor?
        if let file = files.first {
            let fileType = UTType(filenameExtension: file.pathExtension)
            if files.count == 1 && (fileType?.conforms(to: .movie) == true || fileType?.conforms(to: .video) == true) {
                kind = .video
            } else if files.count == 1 && fileType?.conforms(to: .image) == true {
                kind = .image
            } else {
                kind = .file
            }
            title = files.count == 1 ? file.lastPathComponent : "\(file.lastPathComponent) 等 \(files.count) 项"
            searchable = files.map(\.path).joined(separator: "\n")
            swatch = nil
        } else if video != nil {
            kind = .video
            title = "视频"
            searchable = title
            swatch = nil
        } else if imageData != nil {
            kind = .image
            title = "图片"
            searchable = title
            swatch = nil
        } else if let color {
            kind = .color
            title = color.hex
            searchable = color.hex
            swatch = color
        } else {
            let text = plainText ?? "剪贴板内容"
            let isURL = items.joined().contains { $0.type == urlType }
            let richTypes = [NSPasteboard.PasteboardType.rtf.rawValue, NSPasteboard.PasteboardType.html.rawValue,
                             NSPasteboard.PasteboardType.rtfd.rawValue, "com.apple.flat-rtfd"]
            let isRich = items.joined().contains { richTypes.contains($0.type) }
            let isWebLink = URL(string: text).map { ["https", "http"].contains($0.scheme ?? "") } == true
            kind = isURL || isWebLink ? .link : (isRich ? .richText : .text)
            let visible = text.trimmingCharacters(in: .whitespacesAndNewlines)
            title = visible.isEmpty ? "空白文本" : String(visible.prefix(240))
            searchable = String(text.prefix(24_000))
            swatch = nil
        }
        return ClipSummary(id: fingerprint, kind: kind, title: title, searchable: searchable,
                           source: source, date: date, files: files, swatch: swatch)
    }
}

enum ClipKind: String, Codable {
    case text, richText, link, file, image, video, color

    var label: String {
        switch self {
        case .text: AppText.text("文本")
        case .richText: AppText.text("富文本")
        case .link: AppText.text("链接")
        case .file: AppText.text("文件")
        case .image: AppText.text("图片")
        case .video: AppText.text("视频")
        case .color: AppText.text("颜色")
        }
    }

    var symbol: String {
        switch self {
        case .text: "text.alignleft"
        case .richText: "doc.richtext"
        case .link: "link"
        case .file: "doc"
        case .image: "photo"
        case .video: "film"
        case .color: "paintpalette"
        }
    }

    var canPasteAsText: Bool {
        self == .text || self == .richText || self == .link || self == .color
    }
}

struct ClipColor: Codable, Equatable {
    let red: Double
    let green: Double
    let blue: Double
    let alpha: Double

    init(red: Double, green: Double, blue: Double, alpha: Double) {
        self.red = red
        self.green = green
        self.blue = blue
        self.alpha = alpha
    }

    init?(hex: String) {
        guard hex.hasPrefix("#") else { return nil }
        var digits = String(hex.dropFirst())
        if digits.count == 3 || digits.count == 4 { digits = digits.map { "\($0)\($0)" }.joined() }
        guard digits.count == 6 || digits.count == 8, let value = UInt32(digits, radix: 16) else { return nil }
        let rgba = digits.count == 6 ? (value << 8) | 255 : value
        self.init(red: Double((rgba >> 24) & 255) / 255, green: Double((rgba >> 16) & 255) / 255,
                  blue: Double((rgba >> 8) & 255) / 255, alpha: Double(rgba & 255) / 255)
    }

    var hex: String {
        let bytes = [red, green, blue, alpha].map { Int((min(max($0, 0), 1) * 255).rounded()) }
        let format = bytes[3] == 255 ? "#%02X%02X%02X" : "#%02X%02X%02X%02X"
        return String(format: format, arguments: Array(bytes.prefix(bytes[3] == 255 ? 3 : 4)))
    }
}

struct ClipSummary: Codable, Identifiable {
    let id: String
    let kind: ClipKind
    let title: String
    let searchable: String
    let source: String
    let date: Date
    let files: [URL]
    let swatch: ClipColor?

    // Localize generated labels at presentation time; payloads and saved summaries stay unchanged.
    var displayTitle: String {
        if let file = files.first {
            return files.count == 1 ? file.lastPathComponent
                : AppText.format("%@ 等 %@ 项", file.lastPathComponent, files.count)
        }
        if kind == .image || kind == .video { return kind.label }
        if (kind == .text || kind == .richText) && searchable.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return AppText.text("空白文本")
        }
        return title
    }
}
